    23	    private static void siftDown(double[] a, int i, int size) {
    24	        for (int child = 2 * i + 1; child < size; i = child, child = 2 * i + 1) {
    25	            if (child + 1 < size && a[child + 1] > a[child]) {
    26	                child++;
    27	            }
    28	            if (a[i] >= a[child]) {
    29	                return;
    30	            }
    31	            swap(a, i, child);
    32	        }
